insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_027', 'fq_conc_027', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. The Cradle Expanse is a contested zone between factions", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen. Rian trusts a footprint more than a faction''s version of the map.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: An old marker places this disturbance beside infrastructure built before Nexus had a name. In Inner Cradle Exclusion, Kill INNER_CRADLE_MUTANT x5. Rian trusts a footprint more than a faction''s version of the map.", "options": [{"text": "Confirm assignment: Broken Charter: Measure of Resolve 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 138)
