insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_097', 'fq_conc_097', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. The Final Seal — The World Engine requires one final calibration", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. Vale will report the limits of Concordium control as clearly as its gains.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The Outer Ring remains contested; securing it is a continuing responsibility, not a finished map. In Eternal Gate, Kill ABYSS_HARBINGER x1. Vale will report the limits of Concordium control as clearly as its gains.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: Aethel Aftershock 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 208)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_098', 'fq_conc_098', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. One Step from Eternity — Only one step remains before absolute transcendence", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Vale will report the limits of Concordium control as clearly as its gains.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The Outer Ring remains contested; securing it is a continuing responsibility, not a finished map. In Eternal Gate, Kill ABYSS_HARBINGER x1. Vale will report the limits of Concordium control as clearly as its gains.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: The Unquiet Machine 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 209)
