insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_099', 'fq_conc_099', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. The Eternal Crown — The deepest level of Void Echo Chasm holds the Eternal Crown", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Vale will report the limits of Concordium control as clearly as its gains.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The Outer Ring remains contested; securing it is a continuing responsibility, not a finished map. In Eternal Gate, Kill ABYSS_HARBINGER x1. Vale will report the limits of Concordium control as clearly as its gains.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: Terms of Passage 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 210)
