values ('dialog_fq_arc_015', 'fq_arc_015', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "Ah, Scholar. What the Signal Hides — Something is actively corrupting the Aethelgardian signal in the Resonance ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Knowledge demands risk. The Concordium wants to regulate the Shard. The Hegemony wants to weaponize it. We want to understand it.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: Outer Ring Report 01. In Resonance Caverns: Defeat 4 RESONANCE_BAT. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 226)
