values ('dialog_fq_arc_088', 'fq_arc_088', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "Perfect timing. I have a hypothesis to test. The Aethel Siphon Core is now the Arcanum''s primary research facility", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Knowledge demands risk. The Concordium wants to regulate the Shard. The Hegemony wants to weaponize it. We want to understand it.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Prima Materia Thesis: A Narrow Passage 05. In Eternal Gate: Defeat 1 ABYSS_HARBINGER. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 299)
