values ('dialog_fq_iron_022', 'fq_iron_022', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. Drone Sweep — Titan Assembly Drones still function on ancient protocols", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Ravine Doctrine: Broken Signal 02. In War Machine Graveyard: Defeat 1 WAR_MACHINE_SENTINEL. Hold the line and report the condition of the route when the work is done.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 333)
