values ('dialog_msq_lv5_class_intro', 'msq_lv5_class_intro', 'npc_class_advisor', 'start', '[{"id": "start", "text": "Your First Calling", "options": [{"text": "Accept Quest", "next": "confirm_accept", "action": ""}, {"text": "Details...", "next": "details", "action": ""}, {"text": "Not right now.", "next": "exit", "action": "exit"}]}, {"id": "details", "text": "Objectives:\n• Speak with class_trainer\n• Speak with class_change_screen\n\nRewards: 250 EXP · 100 currency · 50 CRD", "options": [{"text": "Accept Quest", "next": "confirm_accept", "action": ""}, {"text": "Go back.", "next": "start", "action": ""}]}, {"id": "confirm_accept", "text": "Confirm that you are ready to take this assignment.", "options": [{"text": "Confirm acceptance", "next": "exit", "action": "accept_quest"}, {"text": "Return to the briefing", "next": "start", "action": ""}]}]'::jsonb, 'dialog_quests.json', 810)
